const input = require("fs").readFileSync(0, "utf8");

function combinationSum(candidates, target) {
  const sorted = [...candidates].sort((a, b) => a - b);
  const combinations = [];
  const path = [];

  // Adds numbers from index start on to path, whose numbers add up to total.
  function build(start, total) {
    if (total === target) {
      combinations.push([...path]);
      return;
    }
    for (let i = start; i < sorted.length; i++) {
      const num = sorted[i];
      if (total + num > target) {
        break;
      }
      path.push(num);
      build(i, total + num);
      path.pop();
    }
  }

  build(0, 0);
  return combinations;
}

