import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;
import java.util.StringJoiner;

public class Main {
    // Adds numbers from index start on to path, whose numbers add up to total.
    static void build(int[] candidates, int target, int start, int total, List<Integer> path,
                      List<List<Integer>> combinations) {
        if (total == target) {
            combinations.add(new ArrayList<>(path));
            return;
        }
        for (int i = start; i < candidates.length; i++) {
            int num = candidates[i];
            if (total + num > target) {
                break;
            }
            path.add(num);
            build(candidates, target, i, total + num, path, combinations);
            path.remove(path.size() - 1);
        }
    }

    static List<List<Integer>> combinationSum(int[] candidates, int target) {
        Arrays.sort(candidates);
        List<List<Integer>> combinations = new ArrayList<>();
        build(candidates, target, 0, 0, new ArrayList<>(), combinations);
        return combinations;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int[] candidates = new int[n];
        for (int i = 0; i < n; i++) {
            candidates[i] = in.nextInt();
        }
        int target = in.nextInt();
        List<List<Integer>> combinations = combinationSum(candidates, target);
        if (combinations.isEmpty()) {
            System.out.println("none");
        }
        for (List<Integer> combination : combinations) {
            StringJoiner line = new StringJoiner(" ");
            for (int num : combination) {
                line.add(String.valueOf(num));
            }
            System.out.println(line);
        }
    }
}

