package main

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

func combinationSum(candidates []int, target int) [][]int {
	sort.Ints(candidates)
	combinations := [][]int{}
	path := []int{}

	// Adds numbers from index start on to path, whose numbers add up to total.
	var build func(start, total int)
	build = func(start, total int) {
		if total == target {
			combinations = append(combinations, append([]int{}, path...))
			return
		}
		for i := start; i < len(candidates); i++ {
			num := candidates[i]
			if total+num > target {
				break
			}
			path = append(path, num)
			build(i, total+num)
			path = path[:len(path)-1]
		}
	}

	build(0, 0)
	return combinations
}

func main() {
	var n int
	fmt.Scan(&n)
	candidates := make([]int, n)
	for i := range candidates {
		fmt.Scan(&candidates[i])
	}
	var target int
	fmt.Scan(&target)
	combinations := combinationSum(candidates, target)
	if len(combinations) == 0 {
		fmt.Println("none")
	}
	for _, combination := range combinations {
		parts := make([]string, len(combination))
		for i, num := range combination {
			parts[i] = strconv.Itoa(num)
		}
		fmt.Println(strings.Join(parts, " "))
	}
}

